query.base:
TS metrics-gcp.bigquery.otel-*
// Non-interactive jobs in PENDING state: batch-priority queries plus load, copy and extract jobs.
// Batch work is designed to wait for idle capacity, so this rule only fires when the queue almost never drains.
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
  AND `metrics.bigquery.googleapis.com/job/num_in_flight` IS NOT NULL
// Stage 1: one value per minute per logical series (MAX collapses fragmented TSIDs of the same series).
// All states, job types and priorities are read, so every published minute is seen, including minutes
// in which GCP omits the pending series because nothing is queued.
| STATS jobs = MAX(MAX_OVER_TIME(`metrics.bigquery.googleapis.com/job/num_in_flight`))
    BY @timestamp = TBUCKET(1 minute), resource.attributes.project_id, resource.attributes.location, attributes.job_type, attributes.priority, attributes.state
// Backlog: pending jobs, excluding interactive queries. Only query jobs carry priority "interactive", so a series
// with that priority and no job_type label is treated as a query (the interactive queueing rule covers it).
// COALESCE keeps every other unlabelled series (NOT of a null comparison would silently drop it).
| EVAL backlog = CASE(attributes.state == "pending"
    AND NOT (COALESCE(attributes.job_type, "query") == "query" AND COALESCE(attributes.priority, "") == "interactive"), jobs, NULL)
// Series without a job_type label are grouped (and alerted) explicitly as "unknown"
| EVAL attributes.job_type = COALESCE(attributes.job_type, "unknown")
// Stage 2: pending jobs per job type per minute, summed across priorities (NULL when no pending series was reported)
| STATS pending = SUM(backlog)
    BY @timestamp, resource.attributes.project_id, resource.attributes.location, attributes.job_type
// Published minutes per project and location (any job/num_in_flight sample). A published minute without
// a pending sample counts as drained; unpublished minutes are not counted at all.
| INLINE STATS visible_minutes = COUNT_DISTINCT(@timestamp)
    BY resource.attributes.project_id, resource.attributes.location
// Customize: minimum pending jobs for a minute to count as backlogged
| STATS backlogged_minutes = COUNT(*) WHERE pending >= 1,
        visible_minutes = MAX(visible_minutes),
        peak_pending_jobs = MAX(pending),
        last_backlogged_at = MAX(@timestamp) WHERE pending >= 1
    BY resource.attributes.project_id, resource.attributes.location, attributes.job_type
// Unrounded, so the threshold is exact (94.95% must not count as 95%); rounded only for display below
| EVAL backlogged_pct = backlogged_minutes * 100.0 / visible_minutes

breach.segment:
// Customize: alert when jobs were pending in >= 90 one-minute samples and in >= 95% of the published minutes,
// and still pending in the last 20 minutes. job/num_in_flight publishes up to ~12 minutes late, so a 120-minute
// window holds ~108 published minutes; with fewer (collector gaps) the 90-minute floor applies.
// The recency check lets the alert recover soon after the queue drains, even when GCP stops reporting the pending series.
WHERE backlogged_minutes >= 90 AND backlogged_pct >= 95.0 AND last_backlogged_at >= NOW() - 20 minutes
| EVAL backlogged_pct = ROUND(backlogged_pct, 1)
| SORT backlogged_minutes DESC, peak_pending_jobs DESC
| LIMIT 50
